// Run from an isolated Unity 2022.3 project with a TerrainData asset at Assets/Source/Terrain.asset.
// Exports source-authored heights and paint weights; no geometry is generated by AI.
using System;
using System.IO;
using UnityEditor;
using UnityEngine;

public static class UnityTerrainExport
{
    public static void Run()
    {
        var data = AssetDatabase.LoadAssetAtPath<TerrainData>("Assets/Source/Terrain.asset");
        if (data == null) throw new Exception("TerrainData could not be loaded");
        var output = Path.Combine(Directory.GetParent(Application.dataPath).FullName, "Export");
        Directory.CreateDirectory(output);
        int n = data.heightmapResolution;
        var heights = data.GetHeights(0, 0, n, n);
        using (var file = new BinaryWriter(File.Create(Path.Combine(output, "heights.bin"))))
        {
            file.Write(n);
            file.Write(data.size.x);
            file.Write(data.size.y);
            file.Write(data.size.z);
            for (int z = 0; z < n; z++)
                for (int x = 0; x < n; x++) file.Write(heights[z, x]);
        }
        var layers = data.terrainLayers;
        var info = new System.Text.StringBuilder();
        info.AppendLine("heightmap=" + n + " size=" + data.size + " alphamap=" + data.alphamapWidth + "x" + data.alphamapHeight);
        for (int i = 0; i < layers.Length; i++)
            info.AppendLine(i + ": " + (layers[i] ? AssetDatabase.GetAssetPath(layers[i]) : "null"));
        // Record the original painted terrain weights at a useful baking resolution.
        int a = data.alphamapWidth;
        var weights = data.GetAlphamaps(0, 0, a, a);
        using (var file = new BinaryWriter(File.Create(Path.Combine(output, "weights.bin"))))
        {
            file.Write(a);
            file.Write(layers.Length);
            for (int z = 0; z < a; z++)
                for (int x = 0; x < a; x++)
                    for (int i = 0; i < layers.Length; i++) file.Write((byte)Mathf.Clamp(Mathf.RoundToInt(weights[z, x, i] * 255), 0, 255));
        }
        for (int i = 0; i < layers.Length; i++)
        {
            var diffuse = layers[i] ? layers[i].diffuseTexture : null;
            if (!diffuse) continue;
            var path = AssetDatabase.GetAssetPath(diffuse);
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer != null && (!importer.isReadable || importer.textureCompression != TextureImporterCompression.Uncompressed))
            {
                importer.isReadable = true;
                importer.textureCompression = TextureImporterCompression.Uncompressed;
                importer.SaveAndReimport();
                diffuse = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            }
            info.AppendLine("diffuse_" + i + "=" + path + " tile=" + layers[i].tileSize);
        }
        int bakeSize = 1024;
        var baked = new Texture2D(bakeSize, bakeSize, TextureFormat.RGB24, false);
        var pixels = new Color[bakeSize * bakeSize];
        for (int z = 0; z < bakeSize; z++)
        {
            int az = Mathf.Min(a - 1, z * a / bakeSize);
            for (int x = 0; x < bakeSize; x++)
            {
                int ax = Mathf.Min(a - 1, x * a / bakeSize);
                Color color = Color.black;
                for (int i = 0; i < layers.Length; i++)
                {
                    var layer = layers[i];
                    if (!layer || !layer.diffuseTexture) continue;
                    float u = (x + .5f) / bakeSize * data.size.x / layer.tileSize.x;
                    float v = (z + .5f) / bakeSize * data.size.z / layer.tileSize.y;
                    color += layer.diffuseTexture.GetPixelBilinear(u, v) * weights[az, ax, i];
                }
                pixels[z * bakeSize + x] = color;
            }
        }
        baked.SetPixels(pixels);
        baked.Apply();
        File.WriteAllBytes(Path.Combine(output, "terrain_albedo.png"), baked.EncodeToPNG());
        File.WriteAllText(Path.Combine(output, "info.txt"), info.ToString());
        Debug.Log("AtmosFiore terrain export: " + output);
    }
}
